package br.com.saulo.rumoaotaf;
import android.app.*;import android.graphics.Color;import android.os.Bundle;import android.text.*;import android.text.method.DigitsKeyListener;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;

final class Onboarding {
 private final Activity a;private final Ui u;private final Store store;private final JSONObject catalog;private final Runnable done,cancel;
 private JSONObject draft;private int step;private LinearLayout body;private final Map<String,EditText> fields=new HashMap<>();private final Map<String,Spinner> selects=new HashMap<>();private final Map<String,String[]> selectCodes=new HashMap<>();private final Map<String,CheckBox> checks=new HashMap<>();
 Onboarding(Activity a,Store s,JSONObject c,Runnable done,Runnable cancel,Bundle saved){this.a=a;u=new Ui(a);store=s;catalog=c;this.done=done;this.cancel=cancel;try{draft=saved!=null?new JSONObject(saved.getString("draft","{}")):new JSONObject(s.state().getJSONObject("profile").toString());}catch(Exception e){draft=new JSONObject();}step=saved!=null?saved.getInt("step",0):s.state().optBoolean("onboarded")?1:0;}
 Bundle snapshot(){capture(false);Bundle b=new Bundle();b.putString("draft",draft.toString());b.putInt("step",step);return b;}
 void back(){capture(false);if(step>0){step--;show();}else if(store.state().optBoolean("onboarded"))cancel.run();else a.finish();}
 private void put(String key,Object value){try{draft.put(key,value);}catch(JSONException e){throw new IllegalStateException(e);}}
 void show(){
  fields.clear();selects.clear();selectCodes.clear();checks.clear();LinearLayout root=u.column();root.setBackgroundColor(Ui.BG);LinearLayout header=u.column();header.setPadding(u.dp(22),u.dp(22),u.dp(22),u.dp(12));u.add(header,u.text("Rumo",26,Ui.GREEN,true));u.space(header,3);u.add(header,u.text(step==0?"DIETA E TREINO NO SEU RITMO":"ETAPA "+step+" DE 4",11,Ui.MUTED,true));root.addView(header);
  ScrollView scroll=new ScrollView(a);body=u.column();body.setPadding(u.dp(22),u.dp(12),u.dp(22),u.dp(20));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  if(step==0)welcome();else if(step==1)personal();else if(step==2)routine();else if(step==3)restrictions();else review();
  LinearLayout actions=u.row();actions.setPadding(u.dp(18),u.dp(10),u.dp(18),u.dp(14));actions.setBackgroundColor(Color.WHITE);
  if(step>0){TextView back=u.button("Voltar",Ui.BG,Ui.INK,()->{capture(false);step--;show();});actions.addView(back,new LinearLayout.LayoutParams(0,-2,1));}
  TextView next=u.button(step==0?"Começar":step==3?"Conferir meus dados":step==4?"Montar minha rotina":"Continuar",()->{
   try{if(step==4){if(!checks.get("consent").isChecked())throw new IllegalArgumentException("Confirme que leu as informações de uso local.");JSONObject clean=new JSONObject(draft.toString());ArrayList<String> keys=new ArrayList<>();for(Iterator<String> i=clean.keys();i.hasNext();)keys.add(i.next());for(String key:keys)if(key.startsWith("_"))clean.remove(key);store.setProfile(clean);done.run();}
   else if(step==0){step=1;show();}else if(capture(true)){step++;show();}}
   catch(Exception e){new AlertDialog.Builder(a).setTitle("Confira o cadastro").setMessage(e.getMessage()).setPositiveButton("Entendi",null).show();}
  });LinearLayout.LayoutParams np=new LinearLayout.LayoutParams(0,-2,step>0?2:1);if(step>0)np.leftMargin=u.dp(10);actions.addView(next,np);root.addView(actions);a.setContentView(root);
 }
 private void welcome(){LinearLayout hero=u.card(body);hero.setBackground(u.shape(Ui.NAVY,22));u.add(hero,u.text("Um plano que começa pelo seu momento.",30,Color.WHITE,true));u.space(hero,14);u.add(hero,u.text("Conte sua rotina e o que deseja alcançar. Receba um ponto de partida para comer melhor, se movimentar e acompanhar a evolução.",15,Color.rgb(216,232,237),false));u.space(hero,18);u.add(hero,u.text("Seu perfil fica neste celular.\nSem conta e sem envio de dados.",13,Color.rgb(109,229,191),true));u.hint(body,"Sugestões com limites claros","Para adultos. Restrições e saúde são consideradas antes de gerar sugestões. O app não substitui avaliação profissional nem cria dietas clínicas.");if(store.state().optBoolean("legacy"))u.hint(body,"Seus registros foram preservados","A versão anterior foi atualizada. Revise os dados e as informações de saúde antes de montar o novo plano.");if(store.state().optBoolean("onboarded")){u.add(body,u.button("Voltar ao meu acompanhamento",Ui.PALE,Ui.GREEN,cancel));}}
 private void heading(String title,String text){u.section(body,title,text);}
 private void personal(){heading("Vamos conhecer você","Use dados atuais. O apelido é opcional.");input("name","Como quer ser chamado?",false,50);input("weight","Peso atual em kg",true,8);input("height","Altura em cm",true,7);input("age","Idade em anos",true,3);select("sex","Sexo para estimativa energética",new String[]{"Selecione","Masculino","Feminino","Prefiro não informar"},new String[]{"","male","female","unspecified"});u.hint(body,"Por que informar?","Peso, altura, idade e sexo são parâmetros de uma estimativa, não uma medição do seu metabolismo. Sem informar sexo, você pode usar o diário sem meta calórica automática.");}
 private void routine(){heading("Seu objetivo e sua rotina","O ponto de partida considera também sua experiência.");select("goal","Qual é seu foco?",new String[]{"Selecione","Perder peso","Manter físico e condicionamento","Ganhar força e massa","Preparação inicial para TAF"},new String[]{"","lose","maintain","strength","taf"});select("activity","Atividade física no dia a dia",new String[]{"Selecione","Pouco ativo / sedentário","Levemente ativo","Moderadamente ativo","Muito ativo"},new String[]{"","low","light","moderate","high"});select("experience","Experiência com exercícios",new String[]{"Selecione","Começando ou voltando agora","Já treino regularmente"},new String[]{"","beginner","regular"});select("place","Onde vai treinar?",new String[]{"Selecione","Em casa","Na academia"},new String[]{"","home","gym"});check("swim","Sei nadar, tenho acesso a piscina e quero incluir natação",draft.optBoolean("swim"));u.hint(body,"Uma base para criar constância","Ciclo de quatro semanas, com cinco dias de atividade e descanso na quarta e no domingo. As sessões começam conforme sua experiência; nenhuma semana avança sozinha.");}
 private void restrictions(){heading("Alimentação e saúde","Essas respostas mudam as sugestões que o app pode oferecer.");select("diet","Padrão alimentar",new String[]{"Comum / sem padrão específico","Vegetariano (com ovos e laticínios)","Vegano"},new String[]{"common","vegetarian","vegan"});check("meatLunch","Prefiro comer carne somente no almoço",draft.optBoolean("meatLunch"));u.space(body,12);u.add(body,u.text("Restrições alimentares",17,Ui.INK,true));String[][] flags={{"gluten","Sem glúten"},{"lactose","Sem lactose"},{"milk","Alergia ao leite"},{"egg","Alergia a ovos"},{"soy","Alergia à soja"},{"peanut","Alergia a amendoim"},{"nuts","Alergia a castanhas"},{"fish","Alergia a peixes"}};String existing=draft.optJSONArray("restrictions")==null?"":draft.optJSONArray("restrictions").toString();for(String[] flag:flags)check(flag[0],flag[1],existing.contains("\""+flag[0]+"\""));input("restrictionNote","Outra restrição não listada (opcional)",false,2000);u.add(body,u.text("Confira rótulos e contaminação cruzada. Uma restrição escrita no campo livre precisa de ajuste profissional e não será considerada resolvida automaticamente.",12,Ui.MUTED,false));u.space(body,18);
  select("health","Como está sua saúde para começar?",new String[]{"Selecione","Nenhuma condição ou sintoma conhecido","Histórico de lesão articular, sem dor atual","Condição ou sintoma que precisa de avaliação"},new String[]{"","none","joint","clinical"});u.add(body,u.text("A última opção inclui doença cardíaca/renal, diabetes, gestação/amamentação, dor atual ou outra condição que exija orientação individual. O app não diagnostica problemas de saúde.",12,Ui.MUTED,false));input("healthNote","Outra condição ou medicamento a considerar (opcional)",false,2000);u.add(body,u.text("Se descrever uma condição não listada, o app manterá o diário e indicará avaliação antes de gerar plano clínico ou de exercícios.",12,Ui.MUTED,false));
 }
 private void review(){heading("Seu ponto de partida","Confira antes de montar sua rotina.");JSONObject generated;Planner.Decision d=Planner.decide(Recommendations.profile(draft));LinearLayout c=u.card(body);u.add(c,u.text(draft.optString("name").isEmpty()?"Seu perfil":draft.optString("name"),21,Ui.INK,true));u.space(c,9);u.add(c,u.text(draft.optInt("age")+" anos · "+draft.optDouble("height")+" cm · "+draft.optDouble("weight")+" kg\n"+Recommendations.goalLabel(draft.optString("goal")),14,Ui.MUTED,false));u.space(c,14);
  if(d.dietAllowed){try{generated=Recommendations.generate(catalog,draft);int count=0;JSONArray meals=generated.getJSONArray("days").getJSONObject(0).getJSONArray("meals");for(int i=0;i<4;i++)if(meals.getJSONObject(i).getJSONArray("options").length()==3)count++;u.add(c,u.text("Alimentação: estimativa de ≈ "+Math.round(d.target)+" kcal/dia",16,Ui.GREEN,true));u.space(c,7);u.add(c,u.text(count+" de 4 refeições com três opções compatíveis no catálogo. Valores e equivalências são aproximados.",13,Ui.MUTED,false));}catch(Exception e){u.add(c,u.text("O cardápio precisa ser revisto.",14,Ui.MUTED,false));}}
  else u.add(c,u.text(d.dietReason,14,Ui.MUTED,false));u.space(c,15);u.add(c,u.text(d.exerciseAllowed?(d.lowImpact?"Treino: começo leve e de baixo impacto.":"Treino: volume inicial conforme sua experiência."):d.exerciseReason,14,Ui.INK,true));u.space(c,12);u.add(c,u.text("Sugestões educativas baseadas em regras e dados de alimentos. Nenhum resultado ou aprovação no TAF é garantido.",12,Ui.MUTED,false));check("consent","Entendi: os dados ficam neste celular e as sugestões não substituem orientação profissional.",false);
 }
 private EditText input(String key,String label,boolean numeric,int max){u.add(body,u.text(label,14,Ui.INK,true));EditText e=new EditText(a);Object value=draft.opt(key);String fallback=value==null||value==JSONObject.NULL?"":value.toString();if(numeric&&fallback.endsWith(".0"))fallback=fallback.substring(0,fallback.length()-2);e.setText(draft.optString("_"+key,fallback));e.setContentDescription(label);e.setTextSize(16);e.setInputType(numeric?2|8192:1|131072|16384);if(numeric){e.setKeyListener(DigitsKeyListener.getInstance("0123456789.,"));e.setRawInputType(2|8192);}e.setFilters(new InputFilter[]{new InputFilter.LengthFilter(max)});u.add(body,e);u.space(body,15);fields.put(key,e);return e;}
 private void select(String key,String label,String[] labels,String[] codes){u.add(body,u.text(label,14,Ui.INK,true));Spinner s=new Spinner(a);ArrayAdapter<String> adapter=new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,labels);s.setAdapter(adapter);s.setContentDescription(label);String value=draft.optString(key);for(int i=0;i<codes.length;i++)if(codes[i].equals(value))s.setSelection(i);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,u.dp(55));body.addView(s,lp);u.space(body,13);selects.put(key,s);selectCodes.put(key,codes);}
 private void check(String key,String label,boolean initial){CheckBox c=new CheckBox(a);c.setText(label);c.setTextSize(14);c.setChecked(initial);c.setMinHeight(u.dp(48));u.add(body,c);checks.put(key,c);u.space(body,5);}
 private boolean capture(boolean validate){
  for(Map.Entry<String,EditText> x:fields.entrySet())put("_"+x.getKey(),x.getValue().getText().toString().trim());for(String key:selects.keySet())put(key,selectCodes.get(key)[selects.get(key).getSelectedItemPosition()]);
  try{
   if(step==1){put("name",fields.get("name").getText().toString().trim());if(validate){put("weight",Core.parseWeight(fields.get("weight").getText().toString()));double height=Double.parseDouble(fields.get("height").getText().toString().replace(',','.'));if(!Double.isFinite(height)||height<130||height>220)throw new IllegalArgumentException("Informe altura entre 130 e 220 cm.");put("height",height);String raw=fields.get("age").getText().toString();if(!raw.matches("[0-9]{2,3}"))throw new IllegalArgumentException("Informe sua idade em anos completos.");int age=Integer.parseInt(raw);if(age<18||age>100)throw new IllegalArgumentException("Este aplicativo é para adultos de 18 a 100 anos. Menores precisam de acompanhamento específico.");put("age",age);if(draft.optString("sex").isEmpty())throw new IllegalArgumentException("Escolha a opção de sexo, inclusive se preferir não informar.");}}
   if(step==2){put("swim",checks.get("swim").isChecked());if(validate)for(String key:new String[]{"goal","activity","experience","place"})if(draft.optString(key).isEmpty())throw new IllegalArgumentException("Confira objetivo, atividade, experiência e local de treino.");}
   if(step==3){put("meatLunch",checks.get("meatLunch").isChecked());put("healthNote",fields.get("healthNote").getText().toString().trim());put("restrictionNote",fields.get("restrictionNote").getText().toString().trim());JSONArray flags=new JSONArray();for(String flag:new String[]{"gluten","lactose","milk","egg","soy","peanut","nuts","fish"})if(checks.get(flag).isChecked())flags.put(flag);put("restrictions",flags);if(validate){if(draft.optString("health").isEmpty())throw new IllegalArgumentException("Escolha a opção de saúde que descreve seu momento.");Store.validateProfile(draft);}}
   return true;
  }catch(Exception e){if(validate)throw new IllegalArgumentException(e.getMessage());return false;}
 }
}
